175	export async function POST(request: Request, ctx: RouteContext<"/api/n8n/[event]">) {
176	  const started = Date.now();
177	  const { event } = await ctx.params;
178	  const correlationId = request.headers.get("x-correlation-id") ?? "-";
179	  const done = (status: number, body?: Record<string, unknown>) => {
180	    console.info(JSON.stringify({ n8n: "in", event, correlationId, status, ms: Date.now() - started }));
181	    return reply(status, body);
182	  };
183	
184	  // 1. Before reading the body
185	  const handler = Object.hasOwn(HANDLERS, event) ? HANDLERS[event] : undefined;
186	  if (!handler) return done(404, { error: "unknown event" });
