201	  const secret = process.env.N8N_CALLBACK_SECRET;
202	  if (!secret) return done(500);
203	  const expected = Buffer.from(`sha256=${createHmac("sha256", secret).update(`${timestamp}.${raw}`).digest("hex")}`);
